\begin{definition}[PUF family]\label{def:puf}
Let $\mathsf{rg}$ be a polynomial. A \emph{PUF family} is a pair $\mathsf{PUF}=(\mathsf{PUFSamp},\mathsf{PUFEval})$ of randomized algorithms, neither required to be efficient. On input $1^\lambda$, $\mathsf{PUFSamp}$ outputs an index $\sigma\in\mathcal{I}_\lambda$; each $\sigma$ determines, for every challenge $x\in\{0,1\}^\lambda$, a distribution $\mathcal{D}_\sigma(x)$ over $\{0,1\}^{\mathsf{rg}(\lambda)}$, and $\mathsf{PUFEval}(1^\lambda,\sigma,x)$ returns a sample drawn from $\mathcal{D}_\sigma(x)$. We require three properties.
\begin{enumerate}
\item ($\delta$-reproducibility) For $\sigma\leftarrow\mathsf{PUFSamp}(1^\lambda)$, $x\leftarrow_{\$}\{0,1\}^\lambda$, $y\leftarrow\mathsf{PUFEval}(1^\lambda,\sigma,x)$ and an independent $y'\leftarrow\mathsf{PUFEval}(1^\lambda,\sigma,x)$,
$\Pr[\mathsf{hd}(y,y')\le\delta(\lambda)]\ge 1-\mathsf{negl}(\lambda)$.
\item ($(\gamma,\delta)$-unpredictability) For every adversary $\mathcal{A}$ making at most polynomially many oracle queries,
\[
\Pr\Big[\mathsf{hd}(y,y')\le\delta(\lambda)\ \wedge\ \forall q\in\mathcal{Q}:\ \mathsf{hd}(q,x)\ge\gamma(\lambda)\Big]\le\mathsf{negl}(\lambda),
\]
where $\sigma\leftarrow\mathsf{PUFSamp}(1^\lambda)$, $x\leftarrow_{\$}\{0,1\}^\lambda$, $y\leftarrow\mathcal{A}^{\mathsf{PUFEval}(1^\lambda,\sigma,\cdot)}(x)$, $y'\leftarrow\mathsf{PUFEval}(1^\lambda,\sigma,x)$, and $\mathcal{Q}$ is the list of all oracle queries made by $\mathcal{A}$.
\item (lazy sampler) There is a polynomial-time stateful interactive Turing machine pair $(\mathsf{MSamp},\mathsf{MEval})$ such that for every $n=\mathrm{poly}(\lambda)$ and every sequence $(x_1,\dots,x_n)$ of challenges, the tuples $(Y_1,\dots,Y_n)$ and $(Y'_1,\dots,Y'_n)$ are identically distributed, where $\mathsf{st}\leftarrow\mathsf{MSamp}(1^\lambda)$ and $Y_i\leftarrow\mathsf{MEval}(x_i)$ (with $\mathsf{MEval}$ carrying state across calls), and $\sigma\leftarrow\mathsf{PUFSamp}(1^\lambda)$, $Y'_i\leftarrow\mathsf{PUFEval}(1^\lambda,\sigma,x_i)$.
\end{enumerate}
\end{definition}

\begin{definition}[Fully malicious hardware-token functionality $\mathcal{F}^{\mathsf{HTSamp},\mathsf{M}_{honest}}_{\mathsf{HToken}}$]\label{def:htoken}
The functionality is parameterized by an algorithm $\mathsf{HTSamp}$ and a Turing machine $\mathsf{M}_{honest}$, runs with parties $\mathcal{P}=\{P_1,\dots,P_n\}$ and adversary $\mathcal{A}$, and is \emph{not} required to be efficient. It maintains a list $\mathcal{L}$ of tokens; each token $\mathsf{tok}$ has a unique identifier $\mathsf{tok}.\mathsf{id}\in\{0,1\}^\lambda$, an internal state $\mathsf{tok}.\mathsf{st}$, code $\mathsf{tok}.\mathsf{M}$, a list $\mathsf{tok}.\mathsf{children}$ of tokens embedded inside it, an owner $\mathsf{tok}.\mathsf{owner}$, and a boolean $\mathsf{tok}.\mathsf{honest}$. It answers:
\begin{itemize}
\item $(\texttt{create})$ from $P\in\mathcal{P}$: create $\mathsf{tok}$ with fresh $\mathsf{tok}.\mathsf{id}$, $\mathsf{tok}.\mathsf{honest}:=\mathsf{true}$, $\mathsf{tok}.\mathsf{owner}:=P$, $\mathsf{tok}.\mathsf{children}:=\varnothing$, $\mathsf{tok}.\mathsf{M}:=\mathsf{M}_{honest}$ and $(\mathsf{tok}.\mathsf{st},\mathsf{pubinfo})\leftarrow\mathsf{HTSamp}(1^\lambda)$; add it to $\mathcal{L}$ and return $(\mathsf{tok}.\mathsf{id},\mathsf{pubinfo})$ to $P$.
\item $(\texttt{createmal},\mathsf{M},\mathsf{st},\mathsf{children})$ from $\mathcal{A}$, provided $\mathcal{A}$ owns every token in $\mathsf{children}$: create $\mathsf{tok}$ with fresh identifier, arbitrary code $\mathsf{M}$, arbitrary initial state $\mathsf{st}$, the given children (whose owner becomes \emph{embedded}), $\mathsf{tok}.\mathsf{honest}:=\mathsf{false}$ and $\mathsf{tok}.\mathsf{owner}:=\mathcal{A}$; return $\mathsf{tok}.\mathsf{id}$ to $\mathcal{A}$.
\item $(\texttt{handover},\mathsf{id},P_j)$ from the current owner $P_i$: set $\mathsf{tok}.\mathsf{owner}:=P_j$ and notify $P_j$.
\item $(\texttt{query},\mathsf{id},q)$ from the current owner $P$: run $(a,\mathsf{st}')\leftarrow\mathsf{tok}.\mathsf{M}(\mathsf{tok}.\mathsf{st},q)$, where $\mathsf{tok}.\mathsf{M}$ is an oracle machine with one oracle per child, each oracle query being answered by evaluating that child recursively in the same way; set $\mathsf{tok}.\mathsf{st}:=\mathsf{st}'$ and return $a$ to $P$.
\item $(\texttt{readout},\mathsf{id})$ from $\mathcal{A}$, for a token with $\mathsf{tok}.\mathsf{honest}=\mathsf{false}$ owned by $\mathcal{A}$: return $\mathsf{tok}.\mathsf{st}$ to $\mathcal{A}$.
\item $(\texttt{openup},\mathsf{id})$ from $\mathcal{A}$, for a token with $\mathsf{tok}.\mathsf{honest}=\mathsf{false}$ owned by $\mathcal{A}$: remove $\mathsf{tok}$ from $\mathcal{L}$ and reassign each child's owner to a party of $\mathcal{A}$'s choice.
\end{itemize}
At the end of the execution the long-term output tape of the functionality records all information held by every token that is owned by $\mathcal{A}$, or owned by a token owned by $\mathcal{A}$ through any number of layers.
Writing $\mathcal{F}^{\mathsf{PUFSamp},\mathsf{PUFEval}}_{\mathsf{HToken}}$ means the instantiation in which honest tokens are PUFs: $\mathsf{HTSamp}=\mathsf{PUFSamp}$ and $\mathsf{M}_{honest}$ is the (stateful, lazily sampled) machine computing $\mathsf{PUFEval}(1^\lambda,\sigma,\cdot)$.
\end{definition}

\begin{definition}[Multiple commitment functionality]\label{def:mcom}
Let $S$ (sender) and $R$ (receiver) be two parties and $\ell$ a polynomial. Upon a command $(\texttt{commit},\mathsf{sid},x)$ from $S$ with $x\in\{0,1\}^{\ell(\lambda)}$, the functionality $\mathcal{F}^{S\to R,\ell}_{\mathsf{MCOM}}$ sends $(\texttt{committed},\mathsf{sid})$ to $R$. Upon a command $(\texttt{unveil},\mathsf{sid})$ from $S$, it sends $(\texttt{unveiled},\mathsf{sid},x)$ to $R$ with the matching $\mathsf{sid}$. Further commands $(\texttt{commit})$ or $(\texttt{unveil})$ with the same $\mathsf{sid}$ are ignored.
\end{definition}

\begin{definition}[Everlasting UC realization with long-term tapes]\label{def:everlasting-uc}
Work in the UC framework, in which a protocol, an adversary $\mathcal{A}$ and an environment $\mathcal{Z}$ are interactive Turing machines and $\mathcal{Z}$ outputs an arbitrary string at the end. Every instance of a machine in the protocol, other than $\mathcal{Z}$ and $\mathcal{A}$, is given an additional output tape called its \emph{long-term output tape}. When $\mathcal{Z}$ produces its output $m$, the adversary $\mathcal{A}$ is invoked once more, this time with all long-term tapes, and produces an output $a$; set $\mathrm{EXC}'_{\pi,\mathcal{A},\mathcal{Z}}(\lambda,z):=(m,a)$. A protocol $\pi$ \emph{everlastingly UC-realizes} an ideal protocol $\rho$ if for every PPT adversary $\mathcal{A}$ there is a PPT simulator $\mathcal{S}$ such that for every PPT environment $\mathcal{Z}$,
\[
\{\mathrm{EXC}'_{\pi,\mathcal{A},\mathcal{Z}}(\lambda,z)\}_{\lambda\in\mathbb{N},\,z\in\{0,1\}^{\mathrm{poly}(\lambda)}}\ \approx\ \{\mathrm{EXC}'_{\rho,\mathcal{S},\mathcal{Z}}(\lambda,z)\}_{\lambda\in\mathbb{N},\,z\in\{0,1\}^{\mathrm{poly}(\lambda)}}.
\]
Corruption is \emph{static}: $\mathcal{Z}$ may issue corruption requests only before the protocol begins.
\end{definition}
